# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe GenerateInvoice::NewLineItemsService do
  it "keeps offering this company's free entry when another company's kept invoice references its id directly and through a link" do
    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    user = create(:user, current_workspace_id: company.id)
    free_entry = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
    null_company_entry = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
    # The save callback refills company_id, so the column is cleared without callbacks.
    null_company_entry.update_column(:company_id, nil)

    other_company = create(:company)
    other_client = create(:client, company: other_company)
    other_invoice = create(:invoice, company: other_company, client: other_client)
    # Ids are global across companies, so another company's rows can name this
    # company's entry id. Validation would refuse these rows, so they are written
    # without it to stand for data that already exists.
    direct_line = create(:invoice_line_item, invoice: other_invoice, timesheet_entry: nil)
    direct_line.update_column(:timesheet_entry_id, free_entry.id)
    aggregate_line = create(:invoice_line_item, invoice: other_invoice, timesheet_entry: nil)
    InvoiceLineItemTimeEntry.new(invoice_line_item: aggregate_line, timesheet_entry_id: free_entry.id).save!(validate: false)

    # "Another company's kept invoices do not change this company's candidate entries from GenerateInvoice::NewLineItemsService"
    offered_ids = described_class.new(client, {}).process[:new_line_item_entries].pluck(:timesheet_entry_id)

    expect(offered_ids).to include(free_entry.id)
    # "Read only kept invoices of the client's company, and only that company's entries."
    expect(offered_ids).not_to include(null_company_entry.id)
  end
end
